HELP_COMMANDS = "bg_kegs(10) · bg_scraps(1000) · bg_card(132102,1) · bg_find('{find}')\\nbg_faction('monsters') · bg_leaders() · bg_allcards() · bg_status()\\nbg_shopcheck() · bg_shoprefill(5) · bg_help()\\nbg_clean_preview() · bg_clean_confirm('DELETE_BETA_GWENT')\\n"

for k, v in T.items():
    assert len(v) == 13, k
    for s in v: assert '"' not in s and '\\' not in s, (k, s)


def ws_function():
    """WitcherScript: BetaGwentConsoleText(key) in the mod text language; CJK falls back to
    English unless the game itself runs in that language (HUD fonts lack CJK glyphs otherwise)."""
    out = ['// Build 12: console and notification texts in the mod text language (top-left setting).',
           'function BetaGwentConsoleLanguage() : int',
           '{',
           '    var language : int;',
           '    language=BetaGwentResolvedTextLanguage();',
           '    if(language<1 || language>13)language=2;',
           '    if(language>=10 && BetaGwentGameTextLanguage()!=language)language=2;',
           '    return language;',
           '}',
           'function BetaGwentConsoleText(key : int) : string',
           '{',
           '    var l : int;',
           '    l=BetaGwentConsoleLanguage();']
    for k, v in T.items():
        out.append('    if(key==%d){' % k)
        for i, s in enumerate(v):
            if i == 1: continue
            out.append('        if(l==%d)return "%s";' % (i + 1, s))
        out.append('        return "%s";' % v[1])
        out.append('    }')
    out += ['    return "";', '}',
            'function BetaGwentConsoleFormat(key : int, optional a : string, optional b : string, optional c : string, optional d : string, optional e : string, optional f : string, optional g : string) : string',
            '{',
            '    var s : string;',
            '    s=BetaGwentConsoleText(key);',
            '    s=StrReplace(s,"{0}",a);s=StrReplace(s,"{1}",b);s=StrReplace(s,"{2}",c);s=StrReplace(s,"{3}",d);',
            '    s=StrReplace(s,"{4}",e);s=StrReplace(s,"{5}",f);s=StrReplace(s,"{6}",g);',
            '    return s;',
            '}',
            'function BetaGwentConsoleHelp() : string',
            '{',
            '    var find : string;',
            '    if(BetaGwentConsoleLanguage()==1)find="Имлерих";else find="Imlerith";',
            '    return StrReplace("%s","{find}",find)+BetaGwentConsoleText(22);' % HELP_COMMANDS,
            '}']
    return '\n'.join(out) + '\n'
